"""This function will ellipsize the string.

    :param msg: Text to ellipsize.
    :param max_size: The maximum size before ellipsizing,
                                    default is 80.
    :return: The ellipsized string if len > max_size, otherwise
                     the original string.
    """
def ellipsize(msg: Any, max_size: Any = 80) -> object {
    if (len(msg) >= max_size) {
        return ("%s (...)" % msg[0:(max_size - 6)]);
    } else {
        return msg;
    }
}

"""Clean a string.

    Trims whitespace.

    Parameters
    ----------
    str : str
        String to be cleaned.

    Returns
    -------
    string
        Cleaned string.

    """
def clean_string(string: Any) -> object {
    assert isinstance(string, str);
    clean_str = string.strip();
    clean_str = clean_str.replace("  ", " ");
    assert isinstance(clean_str, str);
    return clean_str;
}

